@contextmanager
def cli_context(self, command: str) -> Iterator[None]:
    """Lifecycle hook that is called once right after the CLI
    starts.

    `command` is the name of the command passed to monkeytype
    ('run', 'apply', etc).
    """
    store = self.trace_store()
    try:
        yield
    finally:
        if hasattr(store, 'close'):
            store.close()
